final_template:
AWSTemplateFormatVersion: '2010-09-09'
Description: AWS CloudFormation template for creating an IoT Core device onboarding policy scoped to thing name using a Lambda-backed custom resource.

Parameters:
  PolicyNamePrefix:
    Type: String
    Default: DeviceOnboardingPolicy
    Description: Prefix for the IoT device onboarding policy name.
    AllowedPattern: '^[a-zA-Z0-9-_]+$'
    ConstraintDescription: Must contain only alphanumeric characters, hyphens, and underscores.

Resources:
  IoTPolicyManagerRole:
    Type: AWS::IAM::Role
    Properties:
      RoleName: !Sub '${AWS::StackName}-IoTPolicyManagerRole'
      AssumeRolePolicyDocument:
        Version: '2012-10-17'
        Statement:
          - Effect: Allow
            Principal:
              Service: lambda.amazonaws.com
            Action: sts:AssumeRole
      ManagedPolicyArns:
        - arn:aws:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole
      Policies:
        - PolicyName: IoTPolicyManagementAccess
          PolicyDocument:
            Version: '2012-10-17'
            Statement:
              - Effect: Allow
                Action:
                  - iot:CreatePolicy
                  - iot:DeletePolicy
                  - iot:GetPolicy
                  - iot:ListPolicyVersions
                  - iot:DeletePolicyVersion
                Resource: !Sub 'arn:${AWS::Partition}:iot:${AWS::Region}:${AWS::AccountId}:policy/*'

  IoTPolicyManagerLogGroup:
    Type: AWS::Logs::LogGroup
    Properties:
      LogGroupName: !Sub '/aws/lambda/${AWS::StackName}-IoTPolicyManager'
      RetentionInDays: 30

  IoTPolicyManagerFunction:
    Type: AWS::Lambda::Function
    DependsOn: IoTPolicyManagerLogGroup
    Properties:
      FunctionName: !Sub '${AWS::StackName}-IoTPolicyManager'
      Description: Custom resource handler for creating and managing scoped IoT Core device onboarding policies.
      Runtime: nodejs24.x
      Handler: index.handler
      Timeout: 60
      Role: !GetAtt IoTPolicyManagerRole.Arn
      Code:
        ZipFile: |
          const { IoTClient, CreatePolicyCommand, DeletePolicyCommand, ListPolicyVersionsCommand, DeletePolicyVersionCommand } = require('@aws-sdk/client-iot');

          const iotClient = new IoTClient({});

          async function sendResponse(event, context, responseStatus, responseData, physicalResourceId, reason) {
            const responseBody = JSON.stringify({
              Status: responseStatus,
              Reason: reason || `See CloudWatch Log Stream: ${context.logStreamName}`,
              PhysicalResourceId: physicalResourceId || context.logStreamName,
              StackId: event.StackId,
              RequestId: event.RequestId,
              LogicalResourceId: event.LogicalResourceId,
              Data: responseData
            });

            console.log('Sending response:', responseBody);

            const response = await fetch(event.ResponseURL, {
              method: 'PUT',
              headers: {
                'content-type': '',
                'content-length': responseBody.length.toString()
              },
              body: responseBody
            });

            console.log('Response status code:', response.status);
          }

          exports.handler = async (event, context) => {
            console.log('Received event:', JSON.stringify(event, null, 2));

            const requestType = event.RequestType;
            const policyName = event.ResourceProperties.PolicyName;
            const policyDocument = event.ResourceProperties.PolicyDocument;

            try {
              if (requestType === 'Create') {
                console.log(`Creating IoT policy: ${policyName}`);
                const createResult = await iotClient.send(new CreatePolicyCommand({
                  policyName: policyName,
                  policyDocument: JSON.stringify(policyDocument)
                }));

                await sendResponse(event, context, 'SUCCESS', {
                  PolicyName: policyName,
                  PolicyArn: createResult.policyArn
                }, policyName);

              } else if (requestType === 'Update') {
                console.log(`Update requested for policy: ${policyName}`);
                // In CloudFormation, policy update that requires recreate will delete old and create new
                // If policy document or name changed in place, re-create with new PhysicalResourceId if needed
                const oldPolicyName = event.PhysicalResourceId;
                if (oldPolicyName !== policyName) {
                  const createResult = await iotClient.send(new CreatePolicyCommand({
                    policyName: policyName,
                    policyDocument: JSON.stringify(policyDocument)
                  }));
                  await sendResponse(event, context, 'SUCCESS', {
                    PolicyName: policyName,
                    PolicyArn: createResult.policyArn
                  }, policyName);
                } else {
                  await sendResponse(event, context, 'SUCCESS', {
                    PolicyName: policyName
                  }, policyName);
                }

              } else if (requestType === 'Delete') {
                const targetPolicy = event.PhysicalResourceId;
                console.log(`Deleting IoT policy: ${targetPolicy}`);

                try {
                  const versions = await iotClient.send(new ListPolicyVersionsCommand({
                    policyName: targetPolicy
                  }));

                  if (versions.policyVersions) {
                    for (const version of versions.policyVersions) {
                      if (!version.isDefaultVersion) {
                        await iotClient.send(new DeletePolicyVersionCommand({
                          policyName: targetPolicy,
                          policyVersionId: version.versionId
                        }));
                      }
                    }
                  }

                  await iotClient.send(new DeletePolicyCommand({
                    policyName: targetPolicy
                  }));
                } catch (err) {
                  if (err.name === 'ResourceNotFoundException') {
                    console.log(`Policy ${targetPolicy} already deleted.`);
                  } else {
                    throw err;
                  }
                }

                await sendResponse(event, context, 'SUCCESS', {}, targetPolicy);
              }
            } catch (err) {
              console.error('Error handling custom resource:', err);
              await sendResponse(event, context, 'FAILED', {}, event.PhysicalResourceId || policyName, err.message);
            }
          };

  IoTDeviceOnboardingPolicyResource:
    Type: Custom::IoTPolicy
    Properties:
      ServiceToken: !GetAtt IoTPolicyManagerFunction.Arn
      PolicyName: !Sub '${PolicyNamePrefix}-${AWS::StackName}'
      PolicyDocument:
        Version: '2012-10-17'
        Statement:
          - Effect: Allow
            Action:
              - iot:Connect
            Resource:
              - !Sub 'arn:${AWS::Partition}:iot:${AWS::Region}:${AWS::AccountId}:client/$${iot:Connection.Thing.ThingName}'
          - Effect: Allow
            Action:
              - iot:Publish
              - iot:Receive
            Resource:
              - !Sub 'arn:${AWS::Partition}:iot:${AWS::Region}:${AWS::AccountId}:topic/$${iot:Connection.Thing.ThingName}/*'
          - Effect: Allow
            Action:
              - iot:Subscribe
            Resource:
              - !Sub 'arn:${AWS::Partition}:iot:${AWS::Region}:${AWS::AccountId}:topicfilter/$${iot:Connection.Thing.ThingName}/*'

Outputs:
  PolicyName:
    Description: The name of the created IoT device onboarding policy scoped to thing name.
    Value: !GetAtt IoTDeviceOnboardingPolicyResource.PolicyName
    Export:
      Name: !Sub '${AWS::StackName}-PolicyName'
  PolicyArn:
    Description: The ARN of the created IoT device onboarding policy.
    Value: !GetAtt IoTDeviceOnboardingPolicyResource.PolicyArn
    Export:
      Name: !Sub '${AWS::StackName}-PolicyArn'

AWSTemplateFormatVersion: '2010-09-09'
Description: Amazon Verified Permissions Policy Store and Cedar policies for Bookstore application access control.

Parameters:
  SSMParameterName:
    Type: String
    Default: /bookstore/verified-permissions/policy-store-id
    Description: SSM Parameter Store path to store the Verified Permissions Policy Store ID.
  BlockedAdminUserId:
    Type: String
    Default: blocked-admin-user
    Description: Identifier of the specific administrator explicitly forbidden from viewing books.
  SpecificUserId:
    Type: String
    Default: alice
    Description: Identifier of the specific user permitted to view the specific book.
  SpecificBookId:
    Type: String
    Default: special-edition-book-1
    Description: Identifier of the specific book permitted to be viewed by the specific user.
  AllowedRegion:
    Type: String
    Default: United States
    Description: Allowed region value required in request context for book viewing actions.

Resources:
  BookstorePolicyStore:
    Type: AWS::VerifiedPermissions::PolicyStore
    Properties:
      Description: Policy store for the Bookstore application with strict schema validation
      ValidationSettings:
        Mode: STRICT
      Schema:
        CedarJson: !Sub |
          {
            "Bookstore": {
              "entityTypes": {
                "Role": {
                  "memberOfTypes": []
                },
                "User": {
                  "memberOfTypes": [
                    "Role"
                  ],
                  "shape": {
                    "type": "Record",
                    "attributes": {
                      "yearsAsMember": {
                        "type": "Long",
                        "required": false
                      }
                    }
                  }
                },
                "Book": {
                  "memberOfTypes": [],
                  "shape": {
                    "type": "Record",
                    "attributes": {
                      "owner": {
                        "type": "Entity",
                        "name": "User",
                        "required": true
                      }
                    }
                  }
                }
              },
              "actions": {
                "View": {
                  "appliesTo": {
                    "principalTypes": [
                      "User"
                    ],
                    "resourceTypes": [
                      "Book"
                    ],
                    "context": {
                      "type": "Record",
                      "attributes": {
                        "region": {
                          "type": "String",
                          "required": true
                        }
                      }
                    }
                  }
                },
                "ViewWithPremiumOffers": {
                  "appliesTo": {
                    "principalTypes": [
                      "User"
                    ],
                    "resourceTypes": [
                      "Book"
                    ],
                    "context": {
                      "type": "Record",
                      "attributes": {
                        "region": {
                          "type": "String",
                          "required": true
                        }
                      }
                    }
                  }
                }
              }
            }
          }

  PolicyStoreSSMParameter:
    Type: AWS::SSM::Parameter
    Properties:
      Name: !Ref SSMParameterName
      Type: String
      Value: !Ref BookstorePolicyStore
      Description: Amazon Verified Permissions Policy Store ID for the Bookstore application

  AdminViewAnyBookPolicy:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !Ref BookstorePolicyStore
      Definition:
        Static:
          Description: Permit users in Admin role to view any book
          Statement: >-
            permit (
                principal in Bookstore::Role::"Admin",
                action == Bookstore::Action::"View",
                resource is Bookstore::Book
            );

  ForbidBlockedAdminPolicy:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !Ref BookstorePolicyStore
      Definition:
        Static:
          Description: Explicitly forbid one specific named administrator from viewing books
          Statement: !Sub >-
            forbid (
                principal == Bookstore::User::"${BlockedAdminUserId}",
                action == Bookstore::Action::"View",
                resource is Bookstore::Book
            );

  PublisherViewOwnedBooksPolicy:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !Ref BookstorePolicyStore
      Definition:
        Static:
          Description: Permit publishers to view only books they own
          Statement: >-
            permit (
                principal in Bookstore::Role::"Publisher",
                action == Bookstore::Action::"View",
                resource is Bookstore::Book
            )
            when {
                resource.owner == principal
            };

  SpecificUserSpecificBookPolicy:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !Ref BookstorePolicyStore
      Definition:
        Static:
          Description: Permit one specific named user to view one specific named book
          Statement: !Sub >-
            permit (
                principal == Bookstore::User::"${SpecificUserId}",
                action == Bookstore::Action::"View",
                resource == Bookstore::Book::"${SpecificBookId}"
            );

  CustomerViewPremiumOffersQualifiedPolicy:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !Ref BookstorePolicyStore
      Definition:
        Static:
          Description: Permit customers with at least two years of membership to view premium offers
          Statement: >-
            permit (
                principal in Bookstore::Role::"Customer",
                action == Bookstore::Action::"ViewWithPremiumOffers",
                resource is Bookstore::Book
            )
            when {
                principal has yearsAsMember && principal.yearsAsMember >= 2
            };

  CustomerForbidPremiumOffersUnqualifiedPolicy:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !Ref BookstorePolicyStore
      Definition:
        Static:
          Description: Explicitly forbid customers with less than two years of membership from viewing premium offers
          Statement: >-
            forbid (
                principal in Bookstore::Role::"Customer",
                action == Bookstore::Action::"ViewWithPremiumOffers",
                resource is Bookstore::Book
            )
            when {
                principal has yearsAsMember && principal.yearsAsMember < 2
            };

  ForbidNonUSRegionPolicy:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !Ref BookstorePolicyStore
      Definition:
        Static:
          Description: Forbid viewing actions entirely whenever context region is not the United States
          Statement: !Sub >-
            forbid (
                principal,
                action in [Bookstore::Action::"View", Bookstore::Action::"ViewWithPremiumOffers"],
                resource
            )
            when {
                context.region != "${AllowedRegion}"
            };

Outputs:
  PolicyStoreId:
    Description: Identifier of the Verified Permissions Policy Store
    Value: !Ref BookstorePolicyStore
    Export:
      Name: !Sub ${AWS::StackName}-PolicyStoreId
  PolicyStoreArn:
    Description: ARN of the Verified Permissions Policy Store
    Value: !GetAtt BookstorePolicyStore.Arn
    Export:
      Name: !Sub ${AWS::StackName}-PolicyStoreArn
  SSMParameterArn:
    Description: ARN of the SSM Parameter holding the Policy Store ID
    Value: !Sub arn:${AWS::Partition}:ssm:${AWS::Region}:${AWS::AccountId}:parameter${SSMParameterName}

AWSTemplateFormatVersion: '2010-09-09'
Description: AWS Step Functions Calculator demo with Lambda function and Choice state routing.

Resources:
  CalculatorLogGroup:
    Type: AWS::Logs::LogGroup
    Properties:
      LogGroupName: /aws/lambda/Calculator
      RetentionInDays: 3

  CalculatorLambdaRole:
    Type: AWS::IAM::Role
    Properties:
      AssumeRolePolicyDocument:
        Version: '2012-10-17'
        Statement:
          - Effect: Allow
            Principal:
              Service: lambda.amazonaws.com
            Action: sts:AssumeRole
      Policies:
        - PolicyName: CalculatorLambdaLogPolicy
          PolicyDocument:
            Version: '2012-10-17'
            Statement:
              - Effect: Allow
                Action:
                  - logs:CreateLogStream
                  - logs:PutLogEvents
                Resource:
                  - !Sub arn:${AWS::Partition}:logs:${AWS::Region}:${AWS::AccountId}:log-group:/aws/lambda/Calculator:*

  CalculatorLambda:
    Type: AWS::Lambda::Function
    DependsOn: CalculatorLogGroup
    Properties:
      FunctionName: Calculator
      Runtime: nodejs20.x
      Handler: index.handler
      Role: !GetAtt CalculatorLambdaRole.Arn
      Timeout: 10
      Code:
        ZipFile: |
          exports.handler = async (event) => {
            const { operator, operands } = event;
            if (!operands || !Array.isArray(operands) || operands.length === 0) {
              throw new Error("Invalid input: 'operands' must be a non-empty array of numbers.");
            }
            let result;
            switch (operator) {
              case 'add':
                result = operands.reduce((acc, curr) => acc + curr, 0);
                break;
              case 'subtract':
                result = operands.slice(1).reduce((acc, curr) => acc - curr, operands[0]);
                break;
              case 'multiply':
                result = operands.reduce((acc, curr) => acc * curr, 1);
                break;
              case 'divide':
                result = operands.slice(1).reduce((acc, curr) => {
                  if (curr === 0) {
                    throw new Error("Division by zero error.");
                  }
                  return acc / curr;
                }, operands[0]);
                break;
              default:
                throw new Error(`Unsupported operator: ${operator}`);
            }
            return {
              operator,
              operands,
              result
            };
          };

  StateMachineRole:
    Type: AWS::IAM::Role
    Properties:
      AssumeRolePolicyDocument:
        Version: '2012-10-17'
        Statement:
          - Effect: Allow
            Principal:
              Service: states.amazonaws.com
            Action: sts:AssumeRole
      Policies:
        - PolicyName: LambdaInvokePolicy
          PolicyDocument:
            Version: '2012-10-17'
            Statement:
              - Effect: Allow
                Action:
                  - lambda:InvokeFunction
                Resource:
                  - !GetAtt CalculatorLambda.Arn

  CalculatorStateMachine:
    Type: AWS::StepFunctions::StateMachine
    Properties:
      StateMachineName: Calculator-StateMachine
      RoleArn: !GetAtt StateMachineRole.Arn
      DefinitionString: !Sub |
        {
          "Comment": "Calculator State Machine routing math operations through Lambda",
          "StartAt": "RouteOperator",
          "States": {
            "RouteOperator": {
              "Type": "Choice",
              "Choices": [
                {
                  "Variable": "$.operator",
                  "StringEquals": "add",
                  "Next": "AddOperation"
                },
                {
                  "Variable": "$.operator",
                  "StringEquals": "subtract",
                  "Next": "SubtractOperation"
                },
                {
                  "Variable": "$.operator",
                  "StringEquals": "multiply",
                  "Next": "MultiplyOperation"
                },
                {
                  "Variable": "$.operator",
                  "StringEquals": "divide",
                  "Next": "DivideOperation"
                }
              ],
              "Default": "UnknownOperator"
            },
            "AddOperation": {
              "Type": "Task",
              "Resource": "${CalculatorLambda.Arn}",
              "End": true
            },
            "SubtractOperation": {
              "Type": "Task",
              "Resource": "${CalculatorLambda.Arn}",
              "End": true
            },
            "MultiplyOperation": {
              "Type": "Task",
              "Resource": "${CalculatorLambda.Arn}",
              "End": true
            },
            "DivideOperation": {
              "Type": "Task",
              "Resource": "${CalculatorLambda.Arn}",
              "End": true
            },
            "UnknownOperator": {
              "Type": "Fail",
              "Error": "UnknownOperatorError",
              "Cause": "The specified operator is not supported. Supported operators are: add, subtract, multiply, divide."
            }
          }
        }

Outputs:
  StateMachineArn:
    Description: ARN of the Calculator Step Functions State Machine
    Value: !Ref CalculatorStateMachine

  LambdaFunctionArn:
    Description: ARN of the Calculator Lambda Function
    Value: !GetAtt CalculatorLambda.Arn

  SampleInput:
    Description: Sample JSON input format for the calculator state machine
    Value: '{"operator": "add", "operands": [1, 2]}'

AWSTemplateFormatVersion: '2010-09-09'
Description: AWS CloudFormation template for TodoAPIwithJs AppSync GraphQL API with DynamoDB, GSI, and JavaScript resolvers.

Resources:
  # =========================================================================
  # DynamoDB Table
  # =========================================================================
  TodosTable:
    Type: AWS::DynamoDB::Table
    Properties:
      TableName: TodosTable
      BillingMode: PAY_PER_REQUEST
      AttributeDefinitions:
        - AttributeName: id
          AttributeType: S
        - AttributeName: owner
          AttributeType: S
      KeySchema:
        - AttributeName: id
          KeyType: HASH
      GlobalSecondaryIndexes:
        - IndexName: byOwner
          KeySchema:
            - AttributeName: owner
              KeyType: HASH
          Projection:
            ProjectionType: ALL

  # =========================================================================
  # IAM Role for AppSync DynamoDB Data Source
  # =========================================================================
  AppSyncDynamoDBRole:
    Type: AWS::IAM::Role
    Properties:
      RoleName: AppSyncTodoDynamoDBServiceRole
      AssumeRolePolicyDocument:
        Version: '2012-10-17'
        Statement:
          - Effect: Allow
            Principal:
              Service: appsync.amazonaws.com
            Action: sts:AssumeRole
      Policies:
        - PolicyName: AppSyncDynamoDBPolicy
          PolicyDocument:
            Version: '2012-10-17'
            Statement:
              - Effect: Allow
                Action:
                  - dynamodb:GetItem
                  - dynamodb:PutItem
                  - dynamodb:UpdateItem
                  - dynamodb:DeleteItem
                  - dynamodb:Query
                  - dynamodb:Scan
                Resource:
                  - !GetAtt TodosTable.Arn
                  - !Sub '${TodosTable.Arn}/index/*'

  # =========================================================================
  # AppSync GraphQL API
  # =========================================================================
  TodoGraphQLApi:
    Type: AWS::AppSync::GraphQLApi
    Properties:
      Name: TodoAPIwithJs
      AuthenticationType: API_KEY

  TodoApiKey:
    Type: AWS::AppSync::ApiKey
    Properties:
      ApiId: !GetAtt TodoGraphQLApi.ApiId
      Description: API key for TodoAPIwithJs

  TodoGraphQLSchema:
    Type: AWS::AppSync::GraphQLSchema
    Properties:
      ApiId: !GetAtt TodoGraphQLApi.ApiId
      Definition: |
        type Todo {
          id: ID!
          title: String!
          description: String
          completed: Boolean
          owner: String!
          createdAt: AWSDateTime
          updatedAt: AWSDateTime
        }

        input CreateTodoInput {
          title: String!
          description: String
          completed: Boolean
          owner: String!
        }

        input UpdateTodoInput {
          id: ID!
          title: String
          description: String
          completed: Boolean
          owner: String
        }

        type TodoConnection {
          items: [Todo]
          nextToken: String
        }

        type Query {
          getTodo(id: ID!): Todo
          listTodos(limit: Int, nextToken: String): TodoConnection
          todosByOwner(owner: String!, limit: Int, nextToken: String): TodoConnection
        }

        type Mutation {
          createTodo(input: CreateTodoInput!): Todo
          updateTodo(input: UpdateTodoInput!): Todo
          deleteTodo(id: ID!): Todo
        }

        type Subscription {
          onCreateTodo: Todo
            @aws_subscribe(mutations: ["createTodo"])
          onUpdateTodo: Todo
            @aws_subscribe(mutations: ["updateTodo"])
          onDeleteTodo: Todo
            @aws_subscribe(mutations: ["deleteTodo"])
        }

        schema {
          query: Query
          mutation: Mutation
          subscription: Subscription
        }

  # =========================================================================
  # AppSync Data Source
  # =========================================================================
  TodoTableDataSource:
    Type: AWS::AppSync::DataSource
    Properties:
      ApiId: !GetAtt TodoGraphQLApi.ApiId
      Name: TodosDynamoDBDataSource
      Type: AMAZON_DYNAMODB
      ServiceRoleArn: !GetAtt AppSyncDynamoDBRole.Arn
      DynamoDBConfig:
        AwsRegion: !Ref AWS::Region
        TableName: !Ref TodosTable

  # =========================================================================
  # AppSync JavaScript Functions (APPSYNC_JS)
  # =========================================================================
  CreateTodoFunction:
    Type: AWS::AppSync::FunctionConfiguration
    DependsOn: TodoGraphQLSchema
    Properties:
      ApiId: !GetAtt TodoGraphQLApi.ApiId
      Name: createTodoFunction
      DataSourceName: !GetAtt TodoTableDataSource.Name
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: 1.0.0
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          const id = util.autoId();
          const now = util.time.nowISO8601();
          const item = {
            ...ctx.args.input,
            id,
            completed: ctx.args.input.completed != null ? ctx.args.input.completed : false,
            createdAt: now,
            updatedAt: now,
          };
          return {
            operation: 'PutItem',
            key: util.dynamodb.toMapValues({ id }),
            attributeValues: util.dynamodb.toMapValues(item),
          };
        }

        export function response(ctx) {
          if (ctx.error) {
            util.error(ctx.error.message, ctx.error.type);
          }
          return ctx.result;
        }

  UpdateTodoFunction:
    Type: AWS::AppSync::FunctionConfiguration
    DependsOn: TodoGraphQLSchema
    Properties:
      ApiId: !GetAtt TodoGraphQLApi.ApiId
      Name: updateTodoFunction
      DataSourceName: !GetAtt TodoTableDataSource.Name
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: 1.0.0
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          const { id, ...rest } = ctx.args.input;
          const sets = [];
          const expNames = {};
          const expValues = {};

          expValues[':updatedAt'] = util.time.nowISO8601();
          sets.push('#updatedAt = :updatedAt');
          expNames['#updatedAt'] = 'updatedAt';

          for (const [key, value] of Object.entries(rest)) {
            if (value !== undefined) {
              sets.push(`#${key} = :${key}`);
              expNames[`#${key}`] = key;
              expValues[`:${key}`] = value;
            }
          }

          const expression = `SET ${sets.join(', ')}`;

          return {
            operation: 'UpdateItem',
            key: util.dynamodb.toMapValues({ id }),
            update: {
              expression,
              expressionNames: expNames,
              expressionValues: util.dynamodb.toMapValues(expValues),
            },
          };
        }

        export function response(ctx) {
          if (ctx.error) {
            util.error(ctx.error.message, ctx.error.type);
          }
          return ctx.result;
        }

  DeleteTodoFunction:
    Type: AWS::AppSync::FunctionConfiguration
    DependsOn: TodoGraphQLSchema
    Properties:
      ApiId: !GetAtt TodoGraphQLApi.ApiId
      Name: deleteTodoFunction
      DataSourceName: !GetAtt TodoTableDataSource.Name
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: 1.0.0
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          return {
            operation: 'DeleteItem',
            key: util.dynamodb.toMapValues({ id: ctx.args.id }),
          };
        }

        export function response(ctx) {
          if (ctx.error) {
            util.error(ctx.error.message, ctx.error.type);
          }
          return ctx.result;
        }

  GetTodoFunction:
    Type: AWS::AppSync::FunctionConfiguration
    DependsOn: TodoGraphQLSchema
    Properties:
      ApiId: !GetAtt TodoGraphQLApi.ApiId
      Name: getTodoFunction
      DataSourceName: !GetAtt TodoTableDataSource.Name
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: 1.0.0
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          return {
            operation: 'GetItem',
            key: util.dynamodb.toMapValues({ id: ctx.args.id }),
          };
        }

        export function response(ctx) {
          if (ctx.error) {
            util.error(ctx.error.message, ctx.error.type);
          }
          return ctx.result;
        }

  ListTodosFunction:
    Type: AWS::AppSync::FunctionConfiguration
    DependsOn: TodoGraphQLSchema
    Properties:
      ApiId: !GetAtt TodoGraphQLApi.ApiId
      Name: listTodosFunction
      DataSourceName: !GetAtt TodoTableDataSource.Name
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: 1.0.0
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          const { limit = 20, nextToken } = ctx.args;
          return {
            operation: 'Scan',
            limit,
            nextToken,
          };
        }

        export function response(ctx) {
          if (ctx.error) {
            util.error(ctx.error.message, ctx.error.type);
          }
          const { items = [], nextToken } = ctx.result;
          return { items, nextToken };
        }

  QueryTodosByOwnerFunction:
    Type: AWS::AppSync::FunctionConfiguration
    DependsOn: TodoGraphQLSchema
    Properties:
      ApiId: !GetAtt TodoGraphQLApi.ApiId
      Name: queryTodosByOwnerFunction
      DataSourceName: !GetAtt TodoTableDataSource.Name
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: 1.0.0
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          const { owner, limit = 20, nextToken } = ctx.args;
          return {
            operation: 'Query',
            index: 'byOwner',
            query: {
              expression: '#owner = :owner',
              expressionNames: { '#owner': 'owner' },
              expressionValues: util.dynamodb.toMapValues({ ':owner': owner }),
            },
            limit,
            nextToken,
          };
        }

        export function response(ctx) {
          if (ctx.error) {
            util.error(ctx.error.message, ctx.error.type);
          }
          const { items = [], nextToken } = ctx.result;
          return { items, nextToken };
        }

  # =========================================================================
  # Pipeline Resolvers (APPSYNC_JS)
  # =========================================================================
  CreateTodoResolver:
    Type: AWS::AppSync::Resolver
    DependsOn: TodoGraphQLSchema
    Properties:
      ApiId: !GetAtt TodoGraphQLApi.ApiId
      TypeName: Mutation
      FieldName: createTodo
      Kind: PIPELINE
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: 1.0.0
      PipelineConfig:
        Functions:
          - !GetAtt CreateTodoFunction.FunctionId
      Code: |
        export function request(ctx) {
          return {};
        }

        export function response(ctx) {
          return ctx.prev.result;
        }

  UpdateTodoResolver:
    Type: AWS::AppSync::Resolver
    DependsOn: TodoGraphQLSchema
    Properties:
      ApiId: !GetAtt TodoGraphQLApi.ApiId
      TypeName: Mutation
      FieldName: updateTodo
      Kind: PIPELINE
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: 1.0.0
      PipelineConfig:
        Functions:
          - !GetAtt UpdateTodoFunction.FunctionId
      Code: |
        export function request(ctx) {
          return {};
        }

        export function response(ctx) {
          return ctx.prev.result;
        }

  DeleteTodoResolver:
    Type: AWS::AppSync::Resolver
    DependsOn: TodoGraphQLSchema
    Properties:
      ApiId: !GetAtt TodoGraphQLApi.ApiId
      TypeName: Mutation
      FieldName: deleteTodo
      Kind: PIPELINE
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: 1.0.0
      PipelineConfig:
        Functions:
          - !GetAtt DeleteTodoFunction.FunctionId
      Code: |
        export function request(ctx) {
          return {};
        }

        export function response(ctx) {
          return ctx.prev.result;
        }

  GetTodoResolver:
    Type: AWS::AppSync::Resolver
    DependsOn: TodoGraphQLSchema
    Properties:
      ApiId: !GetAtt TodoGraphQLApi.ApiId
      TypeName: Query
      FieldName: getTodo
      Kind: PIPELINE
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: 1.0.0
      PipelineConfig:
        Functions:
          - !GetAtt GetTodoFunction.FunctionId
      Code: |
        export function request(ctx) {
          return {};
        }

        export function response(ctx) {
          return ctx.prev.result;
        }

  ListTodosResolver:
    Type: AWS::AppSync::Resolver
    DependsOn: TodoGraphQLSchema
    Properties:
      ApiId: !GetAtt TodoGraphQLApi.ApiId
      TypeName: Query
      FieldName: listTodos
      Kind: PIPELINE
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: 1.0.0
      PipelineConfig:
        Functions:
          - !GetAtt ListTodosFunction.FunctionId
      Code: |
        export function request(ctx) {
          return {};
        }

        export function response(ctx) {
          return ctx.prev.result;
        }

  QueryTodosByOwnerResolver:
    Type: AWS::AppSync::Resolver
    DependsOn: TodoGraphQLSchema
    Properties:
      ApiId: !GetAtt TodoGraphQLApi.ApiId
      TypeName: Query
      FieldName: todosByOwner
      Kind: PIPELINE
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: 1.0.0
      PipelineConfig:
        Functions:
          - !GetAtt QueryTodosByOwnerFunction.FunctionId
      Code: |
