    Description: The API Key for authorization
    Value: !GetAtt TodoApiKey.ApiKey

  DynamoDBTableName:
    Description: The DynamoDB table backing the GraphQL API
    Value: !Ref TodosTable

AWSTemplateFormatVersion: '2010-09-09'
Description: Serverless Stripe and Squarespace integration posting sales notifications to SNS for Slack relay.

Parameters:
  SquarespaceApiKey:
    Type: String
    NoEcho: true
    Description: Squarespace Commerce API token for retrieving order and inventory details.
    MinLength: 1
  StripeWebhookSecret:
    Type: String
    NoEcho: true
    Description: Stripe Webhook Signing Secret (e.g., whsec_...) used to verify webhook signatures.
    MinLength: 1

Resources:
  NotificationTopic:
    Type: AWS::SNS::Topic
    Properties:
      DisplayName: Squarespace-Stripe-Slack-Notifications
      TopicName: !Sub '${AWS::StackName}-sales-notifications'

  LambdaExecutionRole:
    Type: AWS::IAM::Role
    Properties:
      AssumeRolePolicyDocument:
        Version: '2012-10-17'
        Statement:
          - Effect: Allow
            Principal:
              Service:
                - lambda.amazonaws.com
            Action:
              - sts:AssumeRole
      ManagedPolicyArns:
        - arn:aws:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole
      Policies:
        - PolicyName: PublishToSNS
          PolicyDocument:
            Version: '2012-10-17'
            Statement:
              - Effect: Allow
                Action:
                  - sns:Publish
                Resource: !Ref NotificationTopic

  WebhookHandlerLogGroup:
    Type: AWS::Logs::LogGroup
    Properties:
      LogGroupName: !Sub '/aws/lambda/${AWS::StackName}-webhook-handler'
      RetentionInDays: 30

  WebhookHandlerFunction:
    Type: AWS::Lambda::Function
    DependsOn:
      - WebhookHandlerLogGroup
    Properties:
      FunctionName: !Sub '${AWS::StackName}-webhook-handler'
      Runtime: nodejs20.x
      Handler: index.handler
      Role: !GetAtt LambdaExecutionRole.Arn
      Timeout: 30
      MemorySize: 256
      Environment:
        Variables:
          SNS_TOPIC_ARN: !Ref NotificationTopic
          SQUARESPACE_API_KEY: !Ref SquarespaceApiKey
          STRIPE_WEBHOOK_SECRET: !Ref StripeWebhookSecret
      Code:
        ZipFile: |
          const { SNSClient, PublishCommand } = require('@aws-sdk/client-sns');
          const https = require('https');
          const crypto = require('crypto');

          const snsClient = new SNSClient({});

          function httpsRequest(options, postData) {
            return new Promise((resolve, reject) => {
              const req = https.request(options, (res) => {
                let data = '';
                res.on('data', (chunk) => { data += chunk; });
                res.on('end', () => {
                  try {
                    const parsed = data ? JSON.parse(data) : {};
                    resolve({ statusCode: res.statusCode, data: parsed });
                  } catch (e) {
                    resolve({ statusCode: res.statusCode, data });
                  }
                });
              });
              req.on('error', reject);
              if (postData) req.write(postData);
              req.end();
            });
          }

          function verifyStripeSignature(payload, sigHeader, secret) {
            if (!sigHeader || !secret) return false;
            const items = sigHeader.split(',').reduce((acc, part) => {
              const [k, v] = part.split('=');
              if (k && v) acc[k.trim()] = v.trim();
              return acc;
            }, {});
            const timestamp = items['t'];
            const signature = items['v1'];
            if (!timestamp || !signature) return false;
            const signedPayload = `${timestamp}.${payload}`;
            const expectedSignature = crypto
              .createHmac('sha256', secret)
              .update(signedPayload, 'utf8')
              .digest('hex');
            return crypto.timingSafeEqual(Buffer.from(signature, 'hex'), Buffer.from(expectedSignature, 'hex'));
          }

          exports.handler = async (event) => {
            console.log('Received event:', JSON.stringify(event));
            const signatureHeader = event.headers['Stripe-Signature'] || event.headers['stripe-signature'];
            const rawBody = event.isBase64Encoded ? Buffer.from(event.body, 'base64').toString('utf8') : event.body;

            const webhookSecret = process.env.STRIPE_WEBHOOK_SECRET;
            if (webhookSecret && !verifyStripeSignature(rawBody, signatureHeader, webhookSecret)) {
              console.error('Invalid Stripe signature');
              return { statusCode: 400, body: JSON.stringify({ error: 'Invalid signature' }) };
            }

            let stripeEvent;
            try {
              stripeEvent = JSON.parse(rawBody);
            } catch (err) {
              return { statusCode: 400, body: JSON.stringify({ error: 'Malformed JSON payload' }) };
            }

            if (stripeEvent.type === 'payment_intent.succeeded' || stripeEvent.type === 'charge.succeeded') {
              const object = stripeEvent.data.object;
              const orderId = object.metadata && (object.metadata.squarespace_order_id || object.metadata.orderId || object.metadata.order_id);
              let squarespaceOrder = null;

              if (orderId && process.env.SQUARESPACE_API_KEY) {
                try {
                  const options = {
                    hostname: 'api.squarespace.com',
                    port: 443,
                    path: `/1.0/commerce/orders/${orderId}`,
                    method: 'GET',
                    headers: {
                      'Authorization': `Bearer ${process.env.SQUARESPACE_API_KEY}`,
                      'User-Agent': 'Squarespace-Stripe-Slack-Integration'
                    }
                  };
                  const res = await httpsRequest(options);
                  if (res.statusCode >= 200 && res.statusCode < 300) {
                    squarespaceOrder = res.data;
                  } else {
                    console.warn(`Squarespace API returned status ${res.statusCode}:`, res.data);
                  }
                } catch (err) {
                  console.error('Failed fetching order details from Squarespace:', err);
                }
              }

              const amount = (object.amount ? (object.amount / 100).toFixed(2) : '0.00');
              const currency = (object.currency || 'USD').toUpperCase();
              let slackText = `*New Sale Processed!*\n• *Payment ID:* ${object.id}\n• *Amount:* $${amount} ${currency}`;

              if (squarespaceOrder) {
                slackText += `\n• *Squarespace Order ID:* ${squarespaceOrder.id || orderId}`;
                if (squarespaceOrder.customerEmail) {
                  slackText += `\n• *Customer:* ${squarespaceOrder.customerEmail}`;
                }
                if (squarespaceOrder.lineItems && squarespaceOrder.lineItems.length > 0) {
                  slackText += '\n• *Items:*';
                  squarespaceOrder.lineItems.forEach(item => {
                    slackText += `\n   - ${item.productName || item.title || 'Product'} (Qty: ${item.quantity || 1})`;
                  });
                }
              } else if (orderId) {
                slackText += `\n• *Associated Order ID:* ${orderId}`;
              }

              const messagePayload = {
                text: slackText,
                stripeEventId: stripeEvent.id,
                eventType: stripeEvent.type,
                timestamp: new Date().toISOString()
              };

              await snsClient.send(new PublishCommand({
                TopicArn: process.env.SNS_TOPIC_ARN,
                Subject: 'New Sale Notification',
                Message: JSON.stringify(messagePayload)
              }));
            }

            return {
              statusCode: 200,
              body: JSON.stringify({ received: true })
            };
          };

  RestApi:
    Type: AWS::ApiGateway::RestApi
    Properties:
      Name: !Sub '${AWS::StackName}-stripe-squarespace-api'
      Description: Webhook ingress for Stripe payments integrated with Squarespace
      EndpointConfiguration:
        Types:
          - REGIONAL

  WebhooksResource:
    Type: AWS::ApiGateway::Resource
    Properties:
      RestApiId: !Ref RestApi
      ParentId: !GetAtt RestApi.RootResourceId
      PathPart: webhooks

  WebhooksPostMethod:
    Type: AWS::ApiGateway::Method
    Properties:
      RestApiId: !Ref RestApi
      ResourceId: !Ref WebhooksResource
      HttpMethod: POST
      AuthorizationType: NONE
      Integration:
        Type: AWS_PROXY
        IntegrationHttpMethod: POST
        Uri: !Sub 'arn:aws:apigateway:${AWS::Region}:lambda:path/2015-03-31/functions/${WebhookHandlerFunction.Arn}/invocations'

  ApiDeployment:
    Type: AWS::ApiGateway::Deployment
    DependsOn:
      - WebhooksPostMethod
    Properties:
      RestApiId: !Ref RestApi

  ApiStage:
    Type: AWS::ApiGateway::Stage
    Properties:
      RestApiId: !Ref RestApi
      DeploymentId: !Ref ApiDeployment
      StageName: prod

  LambdaApiPermission:
    Type: AWS::Lambda::Permission
    Properties:
      Action: lambda:InvokeFunction
      FunctionName: !Ref WebhookHandlerFunction
      Principal: apigateway.amazonaws.com
      SourceArn: !Sub 'arn:aws:execute-api:${AWS::Region}:${AWS::AccountId}:${RestApi}/*/*/*'

  LambdaErrorAlarm:
    Type: AWS::CloudWatch::Alarm
    Properties:
      AlarmName: !Sub '${AWS::StackName}-webhook-errors'
      AlarmDescription: Triggers when the Stripe webhook Lambda function invocation errors exceed zero in a 1-minute period.
      Namespace: AWS/Lambda
      MetricName: Errors
      Dimensions:
        - Name: FunctionName
          Value: !Ref WebhookHandlerFunction
      Statistic: Sum
      Period: 60
      EvaluationPeriods: 1
      Threshold: 0
      ComparisonOperator: GreaterThanThreshold
      TreatMissingData: notBreaching

Outputs:
  WebhookUrl:
    Description: URL to register in the Stripe Dashboard Webhooks settings.
    Value: !Sub 'https://${RestApi}.execute-api.${AWS::Region}.amazonaws.com/prod/webhooks'
  NotificationTopicArn:
    Description: ARN of the SNS Topic for sales notifications to Slack.
    Value: !Ref NotificationTopic
  LambdaFunctionName:
    Description: Name of the Stripe/Squarespace webhook processor Lambda function.
    Value: !Ref WebhookHandlerFunction

AWSTemplateFormatVersion: '2010-09-09'
Description: AWS CloudFormation template for SimpleTodoAPI on AWS AppSync backed by DynamoDB using JavaScript resolvers.

Resources:
  TodoTable:
    Type: AWS::DynamoDB::Table
    Properties:
      BillingMode: PAY_PER_REQUEST
      AttributeDefinitions:
        - AttributeName: id
          AttributeType: S
        - AttributeName: owner
          AttributeType: S
      KeySchema:
        - AttributeName: id
          KeyType: HASH
      GlobalSecondaryIndexes:
        - IndexName: byOwner
          KeySchema:
            - AttributeName: owner
              KeyType: HASH
          Projection:
            ProjectionType: ALL

  AppSyncDynamoDBServiceRole:
    Type: AWS::IAM::Role
    Properties:
      AssumeRolePolicyDocument:
        Version: '2012-10-17'
        Statement:
          - Effect: Allow
            Principal:
              Service: appsync.amazonaws.com
            Action: sts:AssumeRole
      Policies:
        - PolicyName: AppSyncDynamoDBAccess
          PolicyDocument:
            Version: '2012-10-17'
            Statement:
              - Effect: Allow
                Action:
                  - dynamodb:GetItem
                  - dynamodb:PutItem
                  - dynamodb:UpdateItem
                  - dynamodb:DeleteItem
                  - dynamodb:Query
                  - dynamodb:Scan
                Resource:
                  - !GetAtt TodoTable.Arn
                  - !Sub '${TodoTable.Arn}/index/*'

  SimpleTodoAPI:
    Type: AWS::AppSync::GraphQLApi
    Properties:
      Name: SimpleTodoAPI
      AuthenticationType: API_KEY

  TodoApiKey:
    Type: AWS::AppSync::ApiKey
    Properties:
      ApiId: !GetAtt SimpleTodoAPI.ApiId
      Description: Default API Key for SimpleTodoAPI

  TodoGraphQLSchema:
    Type: AWS::AppSync::GraphQLSchema
    Properties:
      ApiId: !GetAtt SimpleTodoAPI.ApiId
      Definition: |
        type Todo {
          id: ID!
          title: String!
          description: String
          owner: String!
          completed: Boolean
          createdAt: String
          updatedAt: String
        }

        type TodoConnection {
          items: [Todo]
          nextToken: String
        }

        input CreateTodoInput {
          id: ID
          title: String!
          description: String
          owner: String!
          completed: Boolean
        }

        input UpdateTodoInput {
          id: ID!
          title: String
          description: String
          owner: String
          completed: Boolean
        }

        type Query {
          getTodo(id: ID!): Todo
          listTodos(limit: Int, nextToken: String): TodoConnection
          listTodosByOwner(owner: String!, limit: Int, nextToken: String): TodoConnection
        }

        type Mutation {
          createTodo(input: CreateTodoInput!): Todo
          updateTodo(input: UpdateTodoInput!): Todo
          deleteTodo(id: ID!): Todo
        }

        schema {
          query: Query
          mutation: Mutation
        }

  TodoDataSource:
    Type: AWS::AppSync::DataSource
    Properties:
      ApiId: !GetAtt SimpleTodoAPI.ApiId
      Name: TodoDynamoDBDataSource
      Type: AMAZON_DYNAMODB
      ServiceRoleArn: !GetAtt AppSyncDynamoDBServiceRole.Arn
      DynamoDBConfig:
        AwsRegion: !Ref AWS::Region
        TableName: !Ref TodoTable

  GetTodoResolver:
    Type: AWS::AppSync::Resolver
    DependsOn: TodoGraphQLSchema
    Properties:
      ApiId: !GetAtt SimpleTodoAPI.ApiId
      TypeName: Query
      FieldName: getTodo
      DataSourceName: !GetAtt TodoDataSource.Name
      Runtime:
        Name: APPSYNC_JS
        Version: 1.0.0
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          return {
            operation: 'GetItem',
            key: util.dynamodb.toMapValues({ id: ctx.args.id }),
          };
        }

        export function response(ctx) {
          return ctx.result;
        }

  ListTodosResolver:
    Type: AWS::AppSync::Resolver
    DependsOn: TodoGraphQLSchema
    Properties:
      ApiId: !GetAtt SimpleTodoAPI.ApiId
      TypeName: Query
      FieldName: listTodos
      DataSourceName: !GetAtt TodoDataSource.Name
      Runtime:
        Name: APPSYNC_JS
        Version: 1.0.0
      Code: |
        export function request(ctx) {
          const { limit = 20, nextToken } = ctx.args;
          return {
            operation: 'Scan',
            limit,
            nextToken,
          };
        }

        export function response(ctx) {
          return {
            items: ctx.result.items,
            nextToken: ctx.result.nextToken,
          };
        }

  ListTodosByOwnerResolver:
    Type: AWS::AppSync::Resolver
    DependsOn: TodoGraphQLSchema
    Properties:
      ApiId: !GetAtt SimpleTodoAPI.ApiId
      TypeName: Query
      FieldName: listTodosByOwner
      DataSourceName: !GetAtt TodoDataSource.Name
      Runtime:
        Name: APPSYNC_JS
        Version: 1.0.0
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          const { owner, limit = 20, nextToken } = ctx.args;
          return {
            operation: 'Query',
            index: 'byOwner',
            query: {
              expression: '#owner = :owner',
              expressionNames: { '#owner': 'owner' },
              expressionValues: util.dynamodb.toMapValues({ ':owner': owner }),
            },
            limit,
            nextToken,
          };
        }

        export function response(ctx) {
          return {
            items: ctx.result.items,
            nextToken: ctx.result.nextToken,
          };
        }

  CreateTodoResolver:
    Type: AWS::AppSync::Resolver
    DependsOn: TodoGraphQLSchema
    Properties:
      ApiId: !GetAtt SimpleTodoAPI.ApiId
      TypeName: Mutation
      FieldName: createTodo
      DataSourceName: !GetAtt TodoDataSource.Name
      Runtime:
        Name: APPSYNC_JS
        Version: 1.0.0
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          const { id = util.autoId(), ...values } = ctx.args.input;
          const now = util.time.nowISO8601();
          const item = {
            id,
            completed: false,
            ...values,
            createdAt: now,
            updatedAt: now,
          };
          return {
            operation: 'PutItem',
            key: util.dynamodb.toMapValues({ id }),
            attributeValues: util.dynamodb.toMapValues(item),
          };
        }

        export function response(ctx) {
          return ctx.result;
        }

  UpdateTodoResolver:
    Type: AWS::AppSync::Resolver
    DependsOn: TodoGraphQLSchema
    Properties:
      ApiId: !GetAtt SimpleTodoAPI.ApiId
      TypeName: Mutation
      FieldName: updateTodo
      DataSourceName: !GetAtt TodoDataSource.Name
      Runtime:
        Name: APPSYNC_JS
        Version: 1.0.0
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          const { id, ...values } = ctx.args.input;
          values.updatedAt = util.time.nowISO8601();

          const expression = [];
          const expressionNames = {};
          const expressionValues = {};

          for (const [key, value] of Object.entries(values)) {
            expression.push(`#${key} = :${key}`);
            expressionNames[`#${key}`] = key;
            expressionValues[`:${key}`] = value;
          }

          return {
            operation: 'UpdateItem',
            key: util.dynamodb.toMapValues({ id }),
            update: {
              expression: `SET ${expression.join(', ')}`,
              expressionNames,
              expressionValues: util.dynamodb.toMapValues(expressionValues),
            },
          };
        }

        export function response(ctx) {
          return ctx.result;
        }

  DeleteTodoResolver:
    Type: AWS::AppSync::Resolver
    DependsOn: TodoGraphQLSchema
    Properties:
      ApiId: !GetAtt SimpleTodoAPI.ApiId
      TypeName: Mutation
      FieldName: deleteTodo
      DataSourceName: !GetAtt TodoDataSource.Name
      Runtime:
        Name: APPSYNC_JS
        Version: 1.0.0
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          return {
            operation: 'DeleteItem',
            key: util.dynamodb.toMapValues({ id: ctx.args.id }),
          };
        }

        export function response(ctx) {
          return ctx.result;
        }

Outputs:
  GraphQLApiId:
    Description: AppSync GraphQL API ID
    Value: !GetAtt SimpleTodoAPI.ApiId

  GraphQLApiUrl:
    Description: AppSync GraphQL Endpoint URL
    Value: !GetAtt SimpleTodoAPI.GraphQLUrl

  GraphQLApiKey:
    Description: AppSync API Key
    Value: !GetAtt TodoApiKey.ApiKey

  DynamoDBTableName:
    Description: DynamoDB Table Name for Todos
    Value: !Ref TodoTable
